/* C03 — community page; discussions belong to THIS community only */
SC.C03={title:p=>SC.C03.valid(p)?T(COMMUNITIES[p.id].name):L('Сообщество недоступно','Community unavailable'),valid:p=>!!COMMUNITIES[p.id]&&(COMMUNITIES[p.id].status!=='review'||ownsCommunity(p.id)),render:(p)=>{if(!SC.C03.valid(p))return unavailable();const id=p.id,c=COMMUNITIES[id];const j=S.joined.has(id)||ownsCommunity(id),pend=S.pendingJoin.has(id);const t=p.t||'disc';
 const discs=S.discussions.filter(d=>d.c===id&&(d.author!=='couple'||activePair())).sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||b.t-a.t);
 const evs=allEventIds().filter(e=>EV(e).community===id&&!isPast(e)&&EV(e).status!=='review');
 const canRead=c.privacy==='open'||j;
 const action=ownsCommunity(id)?`<button class="btn md soft" data-act="cManage">${I.gear}${L('Управление','Manage')}</button>`:j?`<button class="btn md soft" data-act="cLeave">${I.check}${L('Ты участник','Member')}</button>`:pend?`<button class="btn md soft" data-act="cCancelReq">${I.clock}${L('Заявка отправлена','Request sent')}</button>`:`<button class="btn md primary" data-act="cJoin">${c.privacy==='closed'?L('Подать заявку','Request to join'):L('Вступить','Join')}</button>`;
 const tabs=tabsRow([['disc',L('Обсуждения','Discussions'),discs.length||''],['events',L('События','Events'),evs.length||''],['members',L('Участники','Members')],['rules',L('Правила','Rules')]],t,'cTab');
 let body='';
 if(t==='disc')body=!canRead?`<div class="veil" style="min-height:200px"><div class="veil-content"><div class="bar-sk" style="width:70%"></div><div class="bar-sk"></div><div class="bar-sk" style="width:50%"></div><div class="bar-sk"></div></div><div class="veil-glass"><div class="lockdot">${I.lock}</div><b>${L('Обсуждения видят участники','Discussions are for members')}</b><p>${L('Подай заявку — ведущие рассмотрят её.','Request to join — the hosts will review it.')}</p></div></div>`
  :`${j?`<button class="composer" data-go="C07" data-id="${id}">${av('me','sm')}<span>${L('Начать обсуждение','Start a discussion')}</span><span class="ibtn">${I.plus}</span></button>`:''}${discs.length?`<div class="card list">${discs.map(d=>`<button class="disc" data-go="C06" data-id="${d.id}">${d.pinned?`<span class="pill v" style="margin-bottom:6px">${L('Закреплено','Pinned')}</span>`:''}<b>${esc(T(d.title))}</b><p>${esc(T(d.text))}</p><span class="meta">${av(d.author,'xs')}<span>${esc(pname(d.author))}</span><span>·</span><span>${F.rel(d.t)}</span><span>${I.chat}${d.replies.length}</span></span></button>`).join('')}</div>`:empty('chat',L('Обсуждений пока нет','No discussions yet'),j?L('Начни первое — спроси или поделись опытом.','Start the first one — ask or share experience.'):L('Вступи, чтобы начать первое обсуждение.','Join to start the first discussion.'))}
  ${!j&&c.privacy==='open'?``:''}`;
 if(t==='events')body=evs.length?`<div class="evgrid">${evs.map((e,i)=>eventCard(e,{i})).join('')}</div>`:empty('cal',L('Ближайших событий нет','No upcoming events'),'',ownsCommunity(id)?`<button class="btn primary" data-go="E11">${L('Создать событие','Create an event')}</button>`:'');
 if(t==='members'){const hosts=communityHostIds(id);const known=[...(c.seedMembers||[]),...(S.communityRequests[id]||[]).filter(x=>x.status==='approved'&&x.showMember).map(x=>x.p)];const vis=[...new Set(c.knownMembers?known:[...['maya','mia','kai','sofi','kira','dan','noa'],...known])].filter(x=>!!PEOPLE[x]&&!c.mods.includes(x)&&canRead).slice(0,12);body=`<div class="sec" style="margin-top:4px">${L('Ведущие','Hosts')}</div><div class="card list">${hosts.map(m=>personRow(m,{sub:L('ведущий(ая)','host')})).join('')}</div>
  <div class="sec">${pl(C.members(id),['участник','участника','участников'],['member','members'])}</div>${canRead?`<div class="card list">${j&&!ownsCommunity(id)?`<button class="li" data-go="P03">${av('me','')}<span class="tx"><b>${esc(pname('me'))}</b><small>${L('это ты','that’s you')}</small></span>${I.chev}</button>`:''}${vis.map(m=>personRow(m)).join('')}${!vis.length&&ownsCommunity(id)?`<p class="note">${L('Других участников пока нет','No other members yet')}</p>`:''}</div>`:`<p class="note">${L('Список участников доступен после вступления.','The member list is available after joining.')}</p>`}`;}
 if(t==='rules')body=`<div class="card"><ol class="rules">${c.rules.map(x=>`<li>${esc(T(x))}</li>`).join('')}</ol></div>`;
 return `<header class="bar overlay"><button class="ibtn glass" data-back aria-label="${L('Назад','Back')}">${I.back}</button><span style="flex:1"></span><button class="ibtn glass" data-act="cMenu" aria-label="${L('Ещё','More')}">${I.more}</button></header>
 <div class="view nodock top0"><div class="wrap"><div class="cm-hero">${evCover(c)}</div>
 <div class="cm-head"><div class="cv" style="position:relative">${commAv(c)}</div><h2>${esc(T(c.name))}</h2>
 <div class="cm-meta"><span>${I.people}<b id="mcount">${pl(C.members(id),['участник','участника','участников'],['member','members'])}</b></span><span>${c.privacy==='closed'?I.lock:I.globe}${c.privacy==='closed'?L('по заявке','by request'):L('открытое','open')}</span><span>${c.city==='online'?I.video:I.pin}${c.city==='online'?L('онлайн','online'):esc(city(c.city))}</span></div></div>
 ${c.status==='review'?`<div class="alert warn mt12">${I.clock}<span><b>${L('На проверке','In review')}</b>${L('Сообщество видишь только ты, пока его не одобрят.','Only you can see the community until it’s approved.')}</span></div>`:''}
 ${md(T(c.desc),'bio cdesc')}
 <div class="chips mt12">${c.topics.map(x=>`<button class="chip tag" data-go="F04" data-id="${x}">#${esc(topic(x))}</button>`).join('')}</div>
 <div class="row g8 mt16">${action}</div>
 <div style="height:18px"></div>${tabs}${body}</div></div>`;}};
ACT.cTab=a=>setP('t',a.dataset.v);
ACT.cMenu=()=>sheet(()=>({title:esc(T(COMMUNITIES[cur().p.id].name)),body:`<div class="card list">${linkRow({act:'shareProfile',icon:'link',title:L('Скопировать ссылку','Copy link'),noChev:1})}${linkRow({act:'cMute',icon:'belloff',title:L('Не присылать уведомления','Mute notifications'),noChev:1})}${linkRow({act:'report',v:'group',icon:'flag',cls:'danger',title:L('Пожаловаться','Report'),noChev:1})}</div>`}));
ACT.cMute=()=>{closeSheet();toast(L('Уведомления сообщества выключены','Community notifications muted'),{type:'ok'});};
/* C04/C05 — join (rules) or request (closed) */
const communityJoinAllowed=id=>!!S.session&&!!COMMUNITIES[id]&&!ownsCommunity(id)&&COMMUNITIES[id].status!=='review'&&!S.joined.has(id)&&!S.pendingJoin.has(id);
ACT.cJoin=()=>{const id=cur().p.id,c=COMMUNITIES[id];if(!communityJoinAllowed(id)){toast(L('Вступление сейчас недоступно','Joining is not available right now'),{type:'warn'});return;}const o=S.ui.cj={id,ok:false,ans:''};
 sheet(()=>({title:c.privacy==='closed'?L('Заявка в сообщество','Request to join'):L('Правила сообщества','Community rules'),body:`<div class="card flat"><ol class="rules">${c.rules.map(x=>`<li>${esc(T(x))}</li>`).join('')}</ol></div>
 ${c.privacy==='closed'?(c.questions||[]).map((q,i)=>`<label class="field mt16 ${o.err?'err':''}"><span>${esc(T(q))}</span><textarea class="inp" id="cjAns" data-in="cjAns" rows="3" maxlength="300" placeholder="${L('Пара предложений','A couple of sentences')}">${esc(o.ans)}</textarea>${o.err?`<div class="ferr">${I.alert}${o.err}</div>`:`<div class="fhint">${L('Ответ увидят только ведущие. Интимные подробности не нужны.','Only hosts will see your answer. No intimate details needed.')}</div>`}</label>`).join(''):''}
 <button class="check ${o.ok?'on':''} ${o.cerr?'err':''}" data-act="cjOk"><i>${I.check}</i><span>${L('Принимаю правила','I accept the rules')}</span></button>
 `,
 foot:`<button class="btn primary" data-act="cjGo">${c.privacy==='closed'?L('Отправить заявку','Send request'):L('Вступить','Join')}</button>`}),{guard:()=>!!o.ans.trim()||o.ok});};
IN.cjAns=el=>{const o=S.ui.cj;if(o&&S.ui.sheet&&o.id===cur().p.id)o.ans=el.value;};
ACT.cjOk=()=>{const o=S.ui.cj;if(!o||!S.ui.sheet||o.id!==cur().p.id)return;o.ans=$('#cjAns')?.value??o.ans;o.ok=!o.ok;o.cerr=false;resheet();};
ACT.cjGo=a=>{const o=S.ui.cj,sh=S.ui.sheet;if(!o||!sh||o.id!==cur().p.id)return;const id=o.id,c=COMMUNITIES[id];
 const active=()=>S.ui.cj===o&&S.ui.sheet===sh&&cur().p.id===id&&COMMUNITIES[id]===c;
 if(!communityJoinAllowed(id))return;o.ans=$('#cjAns')?.value??o.ans;o.err='';o.cerr=false;
 if(c.privacy==='closed'&&(c.questions||[]).length&&o.ans.trim().length<10)o.err=L('Ответь хотя бы парой предложений','Answer in a couple of sentences');if(!o.ok)o.cerr=true;
 if(o.err||o.cerr){resheet();toast(o.err||L('Нужно принять правила','You need to accept the rules'),{type:'err'});return;}const submitted={ans:o.ans,ok:o.ok,privacy:c.privacy};let sent=false;
 return run(a,()=>{if(!active()||!communityJoinAllowed(id))return;if(o.ans!==submitted.ans||o.ok!==submitted.ok||c.privacy!==submitted.privacy){toast(L('Правки ещё не отправлены. Проверь заявку и отправь снова','Your changes have not been sent. Review the request and send it again'),{type:'warn'});return;}
 if(c.privacy==='closed'){S.pendingJoin.add(id);(S.communityRequests[id]??=[]).push({id:'cr'+Date.now(),p:'me',t:Date.now(),status:'pending',showMember:false,answer:{ru:submitted.ans,en:submitted.ans}});autoResolve();}else S.joined.add(id);sent=true;closeSheet();refresh();const m=$('#mcount');if(m&&c.privacy!=='closed'){m.classList.add('bump');}},{ok:()=>sent?(submitted.privacy==='closed'?L('Заявка отправлена ведущим','Request sent to the hosts'):L(`Ты в «${T(c.name)}»`,`You joined “${T(c.name)}”`)):null});};
ACT.cLeave=()=>{const owner=S,session=S.session,route=cur(),id=route.p.id,c=COMMUNITIES[id];if(!session||!c||ownsCommunity(id)||!S.joined.has(id))return;
 const active=()=>S===owner&&S.session===session&&cur()===route&&COMMUNITIES[id]===c&&S.joined.has(id);return ask({icon:'groups',title:L(`Выйти из «${esc(T(c.name))}»?`,`Leave “${esc(T(c.name))}”?`),text:c.privacy==='closed'?L('Чтобы вернуться, понадобится новая заявка.','You’ll need a new request to come back.'):L('Вернуться можно в любой момент. Твои обсуждения останутся.','You can come back any time. Your discussions stay.'),ok:L('Выйти','Leave'),danger:true}).then(ok=>{if(!ok||!active())return;let left=false;return run(null,()=>{if(!active())return;left=S.joined.delete(id);refresh();},{ok:()=>left?L('Ты вышел(ла) из сообщества','You left the community'):null});});};
ACT.cCancelReq=()=>{const owner=S,session=S.session,route=cur(),id=route.p.id;if(!session||!S.pendingJoin.has(id))return;
 const active=()=>S===owner&&S.session===session&&cur()===route&&S.pendingJoin.has(id);return ask({title:L('Отозвать заявку?','Withdraw request?'),ok:L('Отозвать','Withdraw'),danger:true}).then(ok=>{if(!ok||!active())return;let removed=false;return run(null,()=>{if(!active())return;removed=S.pendingJoin.delete(id);if(removed)for(const req of S.communityRequests[id]||[])if(req.p==='me'&&req.status==='pending'){req.status='withdrawn';req.updated=Date.now();}refresh();},{ok:()=>removed?L('Заявка отозвана','Request withdrawn'):null});});};
ACT.cManage=()=>go('C10',{id:cur().p.id});

/* C06 — discussion thread */
SC.C06={title:()=>L('Обсуждение','Discussion'),valid:p=>!!S.discussions.find(d=>d.id===p.id),render:(p,r)=>{const d=S.discussions.find(x=>x.id===p.id);const c=COMMUNITIES[d.c];if(!SC.C03.valid({id:d.c}))return unavailable();const j=communityMemberCanWrite(d.c,'me','comment');if(d.author==='couple'&&!activePair())return `${bar(L('Обсуждение недоступно','Discussion unavailable'),{back:1})}<div class="view">${empty('lock',L('Совместный профиль отключён','Couple profile is inactive'),'')}</div>`;
 if(c.privacy==='closed'&&!j)return unavailable();
 return `${bar(esc(T(c.name)),{back:1,sm:1,sub:L('Обсуждение','Discussion'),actions:authorPicker()})}<div class="view nodock ${j?'cta1':''}"><div class="wrap">
 <div class="post-h"><button class="who" ${profGo(d.author)}>${av(d.author,'sm')}<span class="tx"><b><span class="nmt">${esc(pname(d.author))}</span>${nameBadges(person(d.author))}</b><small>${F.rel(d.t)}</small></span></button><button class="ibtn ghost sm" data-act="report" data-v="post" aria-label="${L('Пожаловаться','Report')}">${I.flag}</button></div>
 <h2 class="t md" style="margin-top:14px">${esc(T(d.title))}</h2><div style="font-size:15.5px;line-height:1.55">${md(T(d.text))}</div>
 ${mediaPreviews(d.media)}<div class="sec">${pl(d.replies.length,['ответ','ответа','ответов'],['reply','replies'])}</div>
 ${replyTree('d',d.id)||`<p class="note">${L('Ответов пока нет.','No replies yet.')}</p>`}${replyComposer(r)}<p class="author-reason" data-author-reason ${communityAuthorReason(cur().id==='C06'?d.c:p.id)?'':'hidden'}>${esc(communityAuthorReason(d.c,'me','comment'))}</p>
 ${!j?`<div class="alert info mt16">${I.info}<span>${L('Чтобы отвечать, вступи в сообщество.','Join the community to reply.')}</span></div><button class="btn primary mt12" data-back>${L('К сообществу','To the community')}</button>`:''}
 </div></div>${j?`<div class="inputbar"><textarea id="dr" rows="1" placeholder="${L('Ответить в обсуждении…','Reply to the discussion…')}" data-in="grow" data-enter="sendReply">${esc(r.f.dr||'')}</textarea><button class="ibtn send" data-act="sendReply" aria-label="${L('Отправить','Send')}">${I.send}</button></div>`:''}`;}};
ACT.sendReply=()=>{const ticket=authorTicket('me');const route=cur(),d=S.discussions.find(x=>x.id===route.p.id);if(!d||!validAuthor(ticket)||!communityAuthorAllowed(d.c,ticket.id,'comment')){toast(L('Ответить могут только участники сообщества','Only community members can reply'),{type:'warn'});return;}const el=$('#dr'),v=el?.value.trim();if(!v){toast(L('Напиши ответ','Write a reply'),{type:'warn'});el?.focus();return;}identifyReplies('d',d.id);const parent=d.replies.find(c=>c.id===route.replyTarget?.id);if(route.replyTarget&&(!parent||parent.deleted||isBlocked(parent.a)))return;const owner=S,session=S.session,x={id:'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),parent:parent?.id||null,a:ticket.id,sender:pairMember(),text:{ru:v,en:v},t:Date.now(),status:'pending'};d.replies.push(x);route.f.dr='';delete route.replyTarget;route.scrollTo=x.id;refresh();
 const allowed=()=>S===owner&&S.session===session&&validAuthor(ticket)&&S.discussions.includes(d)&&communityAuthorAllowed(d.c,ticket.id,'comment');
 const repaint=()=>{if(cur()===route)refresh();};const send=()=>{if(!allowed())return;x.status='pending';repaint();net().then(()=>{if(!allowed())return;x.status='';notifyReply('d',d.id,x);repaint();}).catch(()=>{if(!allowed())return;x.status='failed';repaint();toast(L('Ответ не отправлен','Reply not sent'),{type:'err',action:{label:L('Повторить','Retry'),fn:send}});});};send();};

/* C07 — new discussion */
SC.C07={title:()=>L('Новое обсуждение','New discussion'),valid:p=>!!COMMUNITIES[p.id]&&(S.joined.has(p.id)||ownsCommunity(p.id)),render:(p,r)=>{const c=COMMUNITIES[p.id];r.media=r.media||[];return `${bar(L('Новое обсуждение','New discussion'),{back:1,sm:1,sub:esc(T(c.name)),actions:authorPicker()})}<div class="view nodock cta1"><div class="wrap">
 <p class="author-reason" data-author-reason ${communityAuthorReason(cur().id==='C06'?d.c:p.id)?'':'hidden'}>${esc(communityAuthorReason(p.id))}</p><button class="btn text" data-act="shareCommunityPartner" ${activePair()&&actionAuthor()==='couple'&&communityAuthorReason(p.id)?'':'hidden'}>${L('Поделиться сообществом с партнёром','Share community with partner')}</button>
 ${field({name:'title',label:L('Тема','Topic'),ph:L('Коротко, о чём разговор','In short, what’s it about'),max:120})}
 ${rteField({name:'text',label:L('Текст','Text'),max:3000,ph:L('Подробности, вопрос или опыт','Details, a question or experience')})}
 <div class="sec">${L('Фото и видео','Photos and videos')}<span class="note">${L('до 6 вложений','up to 6 attachments')}</span></div><button class="btn soft" data-act="discussionMedia">${I.image}${L('Добавить фото или видео','Add photos or videos')}</button>${mediaPreviews(r.media,'discussionMediaRemove')}
 <div class="alert">${I.users3}<span>${L(`Увидят ${c.privacy==='closed'?'только участники':'все, кто открывает сообщество'}. Расширить аудиторию нельзя.`,`Visible to ${c.privacy==='closed'?'members only':'everyone who opens the community'}. The audience can’t be widened.`)}</span></div>
 </div></div><div class="ctabar"><div class="wrap"><button class="btn primary" data-act="cdPost">${L('Опубликовать','Publish')}</button></div></div>`;}};
ACT.cdPost=a=>{const r=cur(),community=r.p.id;
 const ticket=authorTicket('me');const allowed=()=>validAuthor(ticket)&&SC.C07.valid({id:community})&&r.p.id===community&&communityAuthorAllowed(community,ticket.id);
 const denied=()=>toast(communityAuthorReason(community,ticket.id)||L('Обсуждение могут создать участники сообщества','Only community members can create a discussion'),{type:'warn'});
 if(!allowed()){denied();return;}const draft=()=>({title:fv('title'),text:fv('text'),media:copyNavValue(r.media||[])}),submitted=draft();
 r.err={};if(submitted.title.trim().length<5)r.err.title=L('Минимум 5 символов','At least 5 characters');if(submitted.text.trim().length<10&&!submitted.media.length)r.err.text=L('Расскажи подробнее — хотя бы 10 символов','Tell a bit more — at least 10 characters');
 if(Object.keys(r.err).length){refresh();shakeFirstErr();return;}
 let published=false;return run(a,()=>{if(!allowed()){denied();return;}if(JSON.stringify(draft())!==JSON.stringify(submitted)){toast(L('Правки ещё не отправлены. Проверь их и нажми «Опубликовать» снова','Your changes have not been sent. Review them and press Publish again'),{type:'warn'});return;}
 const id='d'+Date.now();S.discussions.unshift({id,c:community,author:ticket.id,sender:pairMember(),t:Date.now(),title:{ru:submitted.title,en:submitted.title},text:{ru:submitted.text,en:submitted.text},media:submitted.media,replies:[]});published=true;r.dirty=false;go('C06',{id},{replace:true});},{ok:()=>published?L('Обсуждение опубликовано','Discussion published'):null});};

/* C08 — create community; C10 — manage */
SC.C08={title:()=>L('Новое сообщество','New community'),render:(p,r)=>{r.f.privacy=r.f.privacy||'open';r.f.topics=r.f.topics||[];r.f.plate=r.f.plate||'lilac';return `${bar(L('Новое сообщество','New community'),{back:1,sm:1})}<div class="view nodock cta1"><div class="wrap">
 <section class="grp"><div class="card form-card">${field({name:'name',label:L('Название','Name'),ph:L('Например, «Верёвка по выходным»','E.g. “Weekend Rope”'),max:50})}
 ${rteField({name:'desc',label:L('О чём сообщество','What it’s about'),max:500})}
 <div class="field ${r.err&&r.err.topics?'err':''}" data-field="topics"><span class="flabel">${L('Интересы','Interests')}<i style="font-style:normal;font-weight:500;color:var(--faint)">${L('1–3','1–3')}</i></span>${chipGroup(topicItems(),r.f.topics,'c8Topic')}${r.err&&r.err.topics?`<div class="ferr">${I.alert}${r.err.topics}</div>`:''}</div>
 <div class="field">${selectRow('c8Priv',L('Кто может вступить','Who can join'),[['open',L('Открытое','Open')],['closed',L('По заявке','By request')],['hidden',L('Скрытое','Hidden')]],r.f.privacy)}</div>
 ${field({name:'rules',label:L('Правила — по одному на строку','Rules — one per line'),textarea:1,max:1000,attrs:'rows="4"',ph:L('Согласие прежде всего','Consent first')})}
 <div class="field"><span class="flabel">${L('Обложка','Cover')}</span><div class="chips">${['lilac','rose','sea','amber','moss','coal'].map(k=>`<button data-act="c8Plate" data-v="${k}" aria-label="${k}" style="position:relative;width:52px;height:52px;border-radius:16px;overflow:hidden;outline:${r.f.plate===k?'3px solid var(--ink)':'0'};outline-offset:2px">${plate(k)}</button>`).join('')}</div></div>
 </div></section></div></div><div class="ctabar"><div class="wrap"><button class="btn primary" data-act="c8Save">${L('Отправить на проверку','Submit for review')}</button></div></div>`;}};
ACT.c8Topic=a=>{const r=cur();const s=r.f.topics;const i=s.indexOf(a.dataset.v);if(i<0&&s.length>=3){toast(L('Не больше 3 интересов','Up to 3 interests'),{type:'warn'});return;}i<0?s.push(a.dataset.v):s.splice(i,1);if(r.err)delete r.err.topics;refresh();};
ACT.c8Priv=a=>{cur().f.privacy=a.dataset.v;refresh();};ACT.c8Plate=a=>{cur().f.plate=a.dataset.v;refresh();};
ACT.c8Save=a=>{const r=cur();r.err={};const nm=fv('name').trim();if(nm.length<3)r.err.name=L('Минимум 3 символа','At least 3 characters');else if(Object.values(COMMUNITIES).some(c=>T(c.name).toLowerCase()===nm.toLowerCase()))r.err.name=L('Такое сообщество уже есть','A community with this name exists');
 if(fv('desc').trim().length<20)r.err.desc=L('Опиши подробнее — минимум 20 символов','Describe it more — at least 20 characters');if(!r.f.topics.length)r.err.topics=L('Выбери хотя бы один интерес','Pick at least one interest');if(!fv('rules').trim())r.err.rules=L('Нужно хотя бы одно правило','At least one rule is needed');
 if(Object.keys(r.err).length){refresh();shakeFirstErr();return;}
 run(a,()=>{const id='c'+Date.now();COMMUNITIES[id]={name:{ru:nm,en:nm},plate:r.f.plate,privacy:r.f.privacy==='hidden'?'closed':r.f.privacy,hidden:r.f.privacy==='hidden',members:0,city:S.me.city||'online',topics:r.f.topics,mods:['me'],desc:{ru:fv('desc'),en:fv('desc')},rules:fv('rules').split('\n').filter(Boolean).map(x=>({ru:x,en:x})),status:'review'};S.managedCommunities.add(id);r.dirty=false;go('C03',{id},{replace:true});autoResolve();},{ok:L('Отправлено на проверку. Пока сообщество видишь только ты','Submitted for review. Only you can see it for now')});};
SC.C10={title:()=>L('Управление','Manage'),valid:p=>!!COMMUNITIES[p.id]&&ownsCommunity(p.id),render:(p)=>{if(!ownsCommunity(p.id))return unavailable();const c=COMMUNITIES[p.id];return `${bar(L('Управление','Manage'),{back:1,sm:1,sub:esc(T(c.name)),actions:authorPicker()})}<div class="view nodock"><div class="wrap">
 <div class="stat3"><div><b>${C.members(p.id)}</b><small>${L('участников','members')}</small></div><div><b>${S.discussions.filter(d=>d.c===p.id).length}</b><small>${L('обсуждений','discussions')}</small></div><div><b>0</b><small>${L('жалоб','reports')}</small></div></div>
 <div class="card list">${linkRow({act:'soon',icon:'doc',tone:'v',title:L('Заявки на вступление','Join requests'),val:(S.communityRequests[p.id]||[]).filter(x=>x.status==='pending').length||'0'})}${linkRow({act:'soon',icon:'flag',tone:'l',title:L('Модерация','Moderation'),sub:L('Жалобы на обсуждения и ответы','Reports on discussions and replies')})}${linkRow({act:'soon',icon:'edit',title:L('Описание и правила','Description and rules')})}${linkRow({act:'soon',icon:'people',title:L('Ведущие','Hosts')})}</div>
 </div></div>`;}};
ACT.soon=()=>toast(L('Этот экран — в следующей версии макета','This screen is in the next prototype version'),{type:'info'});

ACT.discussionMedia=async()=>{const owner=S,r=cur(),files=await pickLocalMedia('image/*,video/*');if(S!==owner||cur()!==r)return;r.media=[...(r.media||[]),...files].slice(0,6);if(files.length){r.dirty=true;refresh();}};
ACT.discussionMediaRemove=a=>{cur().media.splice(+a.dataset.v,1);cur().dirty=true;refresh();};
ACT.cfTopic=a=>{const f=S.ui.cf;f.topics=f.topics||[];const i=f.topics.indexOf(a.dataset.v);i<0?f.topics.push(a.dataset.v):f.topics.splice(i,1);resheet();};


const discussionAfter=SC.C06.after;SC.C06.after=(p,r)=>{discussionAfter?.(p,r);scrollToReply(p);};

ACT.shareCommunityPartner=()=>{const id=cur().id==='C06'?S.discussions.find(d=>d.id===cur().p.id)?.c:cur().p.id;copyReviewLink('C03',{id});};

